	'data_hash_integer' => ['$v hash<int, int> = [10, 20]; $w hash<int, int> = [5 => 30];',
		'local_v.at(scpp::int_t<>{1LL}).native_value() == 20 && local_w.at(scpp::int_t<>{5LL}).native_value() == 30'],
	'data_key_order' => ['$v hash<int> = {first: 1, second: 2,};',
