	'data_duplicate' => ['function store(hash<int> &$out, int &$n): void { $out = {first: $n++, second: $n++, first: $n++}; }',
		'([&]() { scpp::hash_t<scpp::int_t<>> out; out.set(scpp::string_t{"saved"}, scpp::int_t<>{9LL}); scpp::int_t<> n{0LL}; bool caught = false; try { function_store(out, n); } catch (const std::runtime_error& error) { caught = std::string(error.what()) == "data initialization: duplicate key"; } return caught && n.native_value() == 3 && out.size() == 1 && out.at(scpp::string_t{"saved"}).native_value() == 9; }())'],
	'data_duplicate_normalized' => ['function mixedbuild(): mixed { return ["10" => null, 10 => 2]; } function dynamicbuild(): dynamic { return ["10" => false, 10 => 2]; }',
		'([&]() { int caught = 0; try { (void)function_mixedbuild(); } catch (const std::runtime_error& error) { if (std::string(error.what()) == "data initialization: duplicate key") ++caught; } try { (void)function_dynamicbuild(); } catch (const std::runtime_error& error) { if (std::string(error.what()) == "data initialization: duplicate key") ++caught; } return caught == 2; }())'],
	'data_nested_repeated_key' => ['$v dynamic = {name: "parent", child: {name: "child"}, sibling: {name: "sibling"}};',
