	'data_dynamic' => ['$v dynamic = {name: "Alex", settings: {enabled: true}};',
		'local_v.get() && local_v->size() == 2 && local_v->at(scpp::string_t{"settings"}).dynamic_if() && (*local_v->at(scpp::string_t{"settings"}).dynamic_if())->at(scpp::string_t{"enabled"}).bool_value().native_value()'],
	'data_identity' => ['$d dynamic = {}; $v dynamic = {child: $d}; $m mixed = {child: $d}; $other dynamic = {};',
